    this.coins = this.physics.add.staticGroup();
    this.hazards = this.physics.add.staticGroup();
    this.enemies = this.physics.add.group();
    let start = { x: 64, y: 400 }, goalPos = null;

    for (let r = 0; r < ROWS; r++) for (let c = 0; c < def.width; c++) {
      const ch = this.grid[r][c], x = c * TILE, y = r * TILE;
      if (ch === '#') this.solids.create(x + 16, y + 16, 'tile');
      else if (ch === '=') {
        const p = this.solids.create(x + 16, y + 6, 'plat');
        p.body.checkCollision.down = p.body.checkCollision.left = p.body.checkCollision.right = false; // one-way
      } else if (ch === 'c') { this.coins.create(x + 16, y + 16, 'coin'); }
      else if (ch === '^') { const s = this.hazards.create(x + 16, y + 24, 'spike'); s.body.setSize(24, 10); s.body.setOffset(4, 6); }
      else if (ch === 'E') {
