    this.hud = this.add.text(12, 10, '', { fontFamily: 'monospace', fontSize: '20px', color: '#fff', stroke: '#000', strokeThickness: 4 }).setScrollFactor(0).setDepth(10);
    this.totalCoins = this.coins.getLength();
