// Coin Hopper — Phaser 4 / Arcade Physics platformer. No external art: textures are generated at boot.
const TILE = 32, VIEW_W = 800, VIEW_H = 576, ROWS = 18;

// Legend: # ground  = one-way platform  c coin  E enemy  ^ spikes  P player start  G goal flag
// Rows are listed top to bottom; short rows are padded (ground rows pad with '#').
const LEVELS = [
  { name: 'Green Hills', width: 40, rows: [
    '', '', '', '', '', '', '', '', '', '',
    '.............cc',
    '............====',
    '.......c.............cc........c',
    '......===...........====......===',
    '..............ccc',
    '..P................c....E.......c..G',
    '##############...',
    '##############...',
  ]},
  { name: 'Spike Valley', width: 50, rows: [
    '', '', '', '', '', '', '', '', '',
    '................................cc',
    '...............................====',
    '.........................c',
    '.......c................===',
    '......===..........cc',
    '..............cc...==......ccc',
    '.P............^^......................E...^^...G',
    '#########...######....#####...',
    '#########...######....#####...',
  ]},
];

function parseLevel(def) {
  const grid = [];
  for (let r = 0; r < ROWS; r++) {
    const s = def.rows[r] || '';
    grid.push(s.padEnd(def.width, r >= 16 ? '#' : '.').split(''));
  }
  return grid;
}
const solidAt = (grid, c, r) => r >= 0 && r < ROWS && c >= 0 && c < grid[0].length && grid[r][c] === '#';
const countCoins = () => LEVELS.reduce((n, l) => n + l.rows.join('').split('c').length - 1, 0);

class BootScene extends Phaser.Scene {
  constructor() { super('boot'); }
  create() {
    const g = this.make.graphics({ add: false });
    const tex = (key, w, h, draw) => { g.clear(); draw(g); g.generateTexture(key, w, h); };
    tex('tile', 32, 32, g => {
      g.fillStyle(0x6b4423).fillRect(0, 0, 32, 32); g.fillStyle(0x4caf50).fillRect(0, 0, 32, 8);
      g.fillStyle(0x553619).fillRect(6, 16, 6, 4).fillRect(20, 22, 6, 4);
    });
    tex('plat', 32, 12, g => { g.fillStyle(0xb98b4f).fillRect(0, 0, 32, 12); g.fillStyle(0xe0b36f).fillRect(0, 0, 32, 4); });
    tex('player', 24, 32, g => {
      g.fillStyle(0x3b82f6).fillRoundedRect(0, 0, 24, 32, 6);
      g.fillStyle(0xffffff).fillRect(12, 8, 8, 8); g.fillStyle(0x111111).fillRect(16, 10, 4, 5);
    });
    tex('coin', 16, 16, g => { g.fillStyle(0xffd23f).fillCircle(8, 8, 8); g.fillStyle(0xffa800).fillCircle(8, 8, 4); });
    tex('enemy', 28, 26, g => {
      g.fillStyle(0xd7263d).fillRoundedRect(0, 0, 28, 26, 8);
      g.fillStyle(0xffffff).fillRect(5, 6, 7, 7).fillRect(16, 6, 7, 7);
      g.fillStyle(0x111111).fillRect(8, 8, 3, 4).fillRect(19, 8, 3, 4);
      g.fillStyle(0x7a1020).fillRect(4, 20, 8, 6).fillRect(16, 20, 8, 6);
    });
    tex('spike', 32, 16, g => {
      g.fillStyle(0xcfd8dc);
      for (let i = 0; i < 2; i++) g.fillTriangle(i * 16, 16, i * 16 + 8, 0, i * 16 + 16, 16);
    });
    tex('flag', 32, 64, g => {
      g.fillStyle(0xeeeeee).fillRect(4, 0, 4, 64); g.fillStyle(0x22c55e).fillTriangle(8, 2, 32, 12, 8, 24);
    });
    tex('puff', 6, 6, g => { g.fillStyle(0xffffff).fillCircle(3, 3, 3); });
    g.destroy();
    this.scene.start('menu');
  }
}

const label = (scene, y, s, size, color = '#fff') =>
  scene.add.text(VIEW_W / 2, y, s, { fontFamily: 'monospace', fontSize: size + 'px', color, align: 'center' }).setOrigin(0.5);

class MenuScene extends Phaser.Scene {
  constructor() { super('menu'); }
  create() {
    this.cameras.main.setBackgroundColor('#1b2a49');
    label(this, 170, 'COIN HOPPER', 64, '#ffd23f');
    label(this, 290, 'Arrows / WASD to move\nUP / W / SPACE to jump, press again in the air to double jump\nStomp the red blob. Avoid spikes and pits.\nReach the flag.', 18);
    const p = label(this, 450, 'Press SPACE or click to start', 26, '#9be7ff');
    this.tweens.add({ targets: p, alpha: 0.3, yoyo: true, repeat: -1, duration: 600 });
    const go = () => this.scene.start('play', { level: 0, banked: 0, deaths: 0 });
    this.input.keyboard.once('keydown-SPACE', go);
    this.input.once('pointerdown', go);
  }
}

class PlayScene extends Phaser.Scene {
  constructor() { super('play'); }

  init(data) { // reset all per-run state here: the scene instance is reused on restart
    this.levelIdx = data.level ?? 0;
    this.banked = data.banked ?? 0;
    this.deaths = data.deaths ?? 0;
    this.coinsGot = 0;
    this.coyote = 0; this.buffer = 0; this.airJumps = 1;
    this.dead = false; this.finished = false;
  }

  create() {
    const def = LEVELS[this.levelIdx];
    this.grid = parseLevel(def);
    const W = def.width * TILE, H = ROWS * TILE;
    this.cameras.main.setBackgroundColor('#6ec6ff');
    this.physics.world.setBounds(0, 0, W, H, true, true, true, false); // open bottom: pits kill

    this.solids = this.physics.add.staticGroup();
    this.coins = this.physics.add.staticGroup();
    this.hazards = this.physics.add.staticGroup();
    this.enemies = this.physics.add.group();
    let start = { x: 64, y: 400 }, goalPos = { x: W - 64, y: 400 };

    for (let r = 0; r < ROWS; r++) for (let c = 0; c < def.width; c++) {
      const ch = this.grid[r][c], x = c * TILE, y = r * TILE;
      if (ch === '#') this.solids.create(x + 16, y + 16, 'tile');
      else if (ch === '=') {
        const p = this.solids.create(x + 16, y + 6, 'plat');
        const cc = p.body.checkCollision; cc.down = cc.left = cc.right = false; // one-way: solid from above only
      } else if (ch === 'c') this.coins.create(x + 16, y + 16, 'coin');
      else if (ch === '^') {
        const s = this.hazards.create(x + 16, y + 24, 'spike');
        s.body.setSize(24, 10); s.body.setOffset(4, 6);
      } else if (ch === 'E') {
        const e = this.enemies.create(x + 16, y + 19, 'enemy');
        e.setCollideWorldBounds(true); e.dir = -1; e.setVelocityX(-60);
      } else if (ch === 'P') start = { x: x + 16, y: y + 16 };
      else if (ch === 'G') goalPos = { x: x + 16, y: y - 16 };
    }
    this.goal = this.physics.add.staticImage(goalPos.x, goalPos.y, 'flag');

    this.player = this.physics.add.sprite(start.x, start.y, 'player');
    this.player.body.setSize(20, 30).setOffset(2, 2);
    this.player.setCollideWorldBounds(true);
    this.player.body.setMaxVelocityY(900);

    this.physics.add.collider(this.player, this.solids);
    this.physics.add.collider(this.enemies, this.solids);
    this.physics.add.overlap(this.player, this.coins, (_p, coin) => {
      this.burst(coin.x, coin.y, 0xffd23f); coin.destroy(); this.coinsGot++; this.updateHud();
    });
    this.physics.add.overlap(this.player, this.hazards, () => this.die());
    this.physics.add.overlap(this.player, this.enemies, (p, e) => this.hitEnemy(p, e));
    this.physics.add.overlap(this.player, this.goal, () => this.finish());

    this.cameras.main.setBounds(0, 0, W, H);
    this.cameras.main.startFollow(this.player, true, 0.12, 0.12);
    this.cameras.main.fadeIn(250);

    const K = Phaser.Input.Keyboard.KeyCodes;
    this.keys = this.input.keyboard.addKeys({ left: K.LEFT, right: K.RIGHT, up: K.UP, a: K.A, d: K.D, w: K.W, space: K.SPACE });
    this.hud = this.add.text(12, 10, '', { fontFamily: 'monospace', fontSize: '20px', color: '#fff', stroke: '#000', strokeThickness: 4 })
      .setScrollFactor(0).setDepth(10);
    this.totalCoins = this.coins.getLength();
    this.updateHud();
  }

  updateHud() {
    this.hud.setText(`Level ${this.levelIdx + 1}: ${LEVELS[this.levelIdx].name}   Coins ${this.coinsGot}/${this.totalCoins}   Deaths ${this.deaths}`);
  }

  burst(x, y, tint) {
    for (let i = 0; i < 6; i++) {
      const p = this.add.image(x, y, 'puff').setTint(tint);
      this.tweens.add({
        targets: p, x: x + Phaser.Math.Between(-24, 24), y: y + Phaser.Math.Between(-30, 10),
        alpha: 0, duration: 350, onComplete: () => p.destroy(),
      });
    }
  }

  hitEnemy(p, e) {
    if (this.dead || !e.active || !e.body.enable) return;
    const stomp = p.body.velocity.y > 0 && p.body.bottom - e.body.top < 16;
    if (!stomp) return this.die();
    e.disableBody(true, false);
    this.tweens.add({ targets: e, scaleY: 0.1, alpha: 0, duration: 200, onComplete: () => e.destroy() });
    p.setVelocityY(-380); this.airJumps = 1;
    this.cameras.main.shake(80, 0.004);
    this.burst(e.x, e.y, 0xd7263d);
  }

  die() {
    if (this.dead || this.finished) return;
    this.dead = true; this.deaths++;
    this.player.setTint(0xff4444).setVelocity(0, -300);
    this.player.body.checkCollision.none = true;
    this.cameras.main.shake(200, 0.01);
    this.time.delayedCall(700, () => this.scene.restart({ level: this.levelIdx, banked: this.banked, deaths: this.deaths }));
  }

  finish() {
    if (this.finished || this.dead) return;
    this.finished = true;
    this.player.setVelocity(0, 0); this.player.body.setAllowGravity(false);
    const banked = this.banked + this.coinsGot, next = this.levelIdx + 1;
    this.cameras.main.fadeOut(400);
    this.time.delayedCall(450, () => {
      if (next < LEVELS.length) this.scene.start('play', { level: next, banked, deaths: this.deaths });
      else this.scene.start('win', { coins: banked, deaths: this.deaths });
    });
  }

  update(_t, delta) {
    if (this.dead || this.finished) return;
    const dt = delta / 1000, p = this.player, body = p.body, k = this.keys;
    const left = k.left.isDown || k.a.isDown, right = k.right.isDown || k.d.isDown;
    const jumpHeld = k.up.isDown || k.w.isDown || k.space.isDown;
    const jumpPressed = [k.up, k.w, k.space].some(key => Phaser.Input.Keyboard.JustDown(key));

    // horizontal: move velocity toward target speed
    const target = ((right ? 1 : 0) - (left ? 1 : 0)) * 210;
    const accel = (body.blocked.down ? 1800 : 1100) * dt;
    body.velocity.x = Phaser.Math.Clamp(target, body.velocity.x - accel, body.velocity.x + accel);
    if (target !== 0) p.setFlipX(target < 0);

    // jump feel: coyote time, input buffer, one air jump, variable height, heavier fall
    if (body.blocked.down) { this.coyote = 0.1; this.airJumps = 1; } else this.coyote -= dt;
    this.buffer = jumpPressed ? 0.12 : this.buffer - dt;
    if (this.buffer > 0) {
      if (this.coyote > 0) { p.setVelocityY(-520); this.coyote = 0; this.buffer = 0; this.puff(); }
      else if (this.airJumps > 0 && jumpPressed) { p.setVelocityY(-480); this.airJumps--; this.buffer = 0; this.puff(); }
    }
    if (!jumpHeld && body.velocity.y < -200) body.velocity.y = -200; // released early: cut the arc short
    body.setGravityY(body.velocity.y > 0 ? 800 : 0);                // 1200 rising, 2000 falling

    // enemy patrol: turn at walls and ledges
    this.enemies.getChildren().forEach(e => {
      if (!e.active || !e.body.enable) return;
      const front = e.dir > 0 ? e.body.right + 2 : e.body.left - 2;
      const ledge = !solidAt(this.grid, Math.floor(front / TILE), Math.floor((e.body.bottom + 4) / TILE));
      if ((e.body.blocked.left || e.body.blocked.right || ledge) && e.body.blocked.down) e.dir *= -1;
      e.setVelocityX(e.dir * 60); e.setFlipX(e.dir > 0);
    });

    if (p.y > ROWS * TILE + 60) this.die();
  }

  puff() { this.burst(this.player.x, this.player.body.bottom, 0xffffff); }
}

