class WinScene extends Phaser.Scene {
  constructor() { super('win'); }
  init(data) { this.result = data; }
  create() {
    this.cameras.main.setBackgroundColor('#1b2a49');
    const total = LEVELS.reduce((n, l) => n + l.rows.join('').split('c').length - 1, 0);
    const t = (y, s, size, color = '#fff') => this.add.text(VIEW_W / 2, y, s, { fontFamily: 'monospace', fontSize: size + 'px', color, align: 'center' }).setOrigin(0.5);
    t(150, 'YOU WIN!', 80, '#ffd23f');
    t(270, `Coins collected: ${this.result.coins} / ${total}\nDeaths: ${this.result.deaths}`, 28);
    if (this.result.coins === total) t(350, '★ Perfect run! ★', 26, '#9be7ff');
    const p = t(450, 'Press SPACE or click to play again', 24, '#9be7ff');
    this.tweens.add({ targets: p, alpha: 0.3, yoyo: true, repeat: -1, duration: 600 });
    for (let i = 0; i < 40; i++) {
      const c = this.add.image(Phaser.Math.Between(0, VIEW_W), -20, 'coin');
      this.tweens.add({ targets: c, y: VIEW_H + 20, duration: Phaser.Math.Between(1500, 3500), delay: i * 80, repeat: -1 });
    }
    const go = () => this.scene.start('play', { level: 0, banked: 0, deaths: 0 });
    this.input.keyboard.once('keydown-SPACE', go);
    this.input.once('pointerdown', go);
  }
}

window.__game = new Phaser.Game({
  type: Phaser.AUTO, width: VIEW_W, height: VIEW_H, backgroundColor: '#000',
  pixelArt: true,
  scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
  physics: { default: 'arcade', arcade: { gravity: { x: 0, y: 1200 }, debug: false } },
  scene: [BootScene, MenuScene, PlayScene, WinScene],
});
